import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;

const kBrandGreen = Color(0xFF145A4A);
const kBrandTeal = Color(0xFF1F7A68);
const kBrandGold = Color(0xFFC9A44B);
const kBrandCream = Color(0xFFF7F2E8);

const String _logoBase64 = '';
final pw.MemoryImage brandPdfLogo = pw.MemoryImage(base64Decode(_logoBase64));

class BrandLogo extends StatelessWidget {
  final double size;
  const BrandLogo({super.key, this.size = 44});

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      padding: const EdgeInsets.all(2),
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: Colors.white,
        border: Border.all(color: kBrandGold, width: 2),
      ),
      child: ClipOval(
        child: Image.asset(
          'assets/al_amin_logo.png',
          fit: BoxFit.contain,
          errorBuilder: (_, __, ___) => Image.memory(
            base64Decode(_logoBase64),
            fit: BoxFit.contain,
          ),
        ),
      ),
    );
  }
}

class BrandTitle extends StatelessWidget {
  final bool compact;
  const BrandTitle({super.key, this.compact = false});

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        BrandLogo(size: compact ? 34 : 44),
        const SizedBox(width: 10),
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'AL-AMIN BAITUL MAAL',
              style: TextStyle(
                color: kBrandGreen,
                fontWeight: FontWeight.w800,
                fontSize: compact ? 15 : 18,
                letterSpacing: .3,
              ),
            ),
            if (!compact)
              const Text(
                'Regd. No. 5767 • Dangerpora, Malla Bagh, Srinagar',
                style: TextStyle(fontSize: 9, color: Colors.black54),
              ),
          ],
        ),
      ],
    );
  }
}

pw.Widget pdfBrandHeader({String? documentTitle, bool large = false}) {
  final logoSize = large ? 66.0 : 52.0;
  return pw.Column(
    children: [
      pw.Container(
        padding: const pw.EdgeInsets.fromLTRB(12, 10, 12, 10),
        decoration: pw.BoxDecoration(
          color: PdfColor.fromHex('#F7FBF9'),
          borderRadius: pw.BorderRadius.circular(10),
          border: pw.Border.all(color: PdfColor.fromHex('#B9D8CD'), width: .8),
        ),
        child: pw.Row(
          crossAxisAlignment: pw.CrossAxisAlignment.center,
          children: [
            pw.Container(
              width: logoSize,
              height: logoSize,
              decoration: pw.BoxDecoration(
                shape: pw.BoxShape.circle,
                color: PdfColors.white,
                border: pw.Border.all(color: PdfColor.fromHex('#C9A44B'), width: 1.5),
              ),
              padding: const pw.EdgeInsets.all(3),
              child: pw.Image(brandPdfLogo, fit: pw.BoxFit.contain),
            ),
            pw.SizedBox(width: 12),
            pw.Expanded(
              child: pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Text(
                    'AL-AMIN BAITUL MAAL',
                    style: pw.TextStyle(
                      color: PdfColor.fromHex('#145A4A'),
                      fontSize: large ? 20 : 17,
                      fontWeight: pw.FontWeight.bold,
                    ),
                  ),
                  pw.SizedBox(height: 2),
                  pw.Text(
                    'Regd. No. 5767 • Dangerpora, Malla Bagh, Srinagar',
                    style: const pw.TextStyle(fontSize: 8.5, color: PdfColors.grey700),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
      if (documentTitle != null) ...[
        pw.SizedBox(height: 9),
        pw.Container(
          padding: const pw.EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          decoration: pw.BoxDecoration(
            color: PdfColor.fromHex('#145A4A'),
            borderRadius: pw.BorderRadius.circular(6),
          ),
          child: pw.Text(
            documentTitle,
            textAlign: pw.TextAlign.center,
            style: pw.TextStyle(
              color: PdfColors.white,
              fontSize: large ? 14 : 12,
              fontWeight: pw.FontWeight.bold,
            ),
          ),
        ),
      ],
      pw.SizedBox(height: 9),
    ],
  );
}
